package com.ribaut.watchdesigner;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.*;
import android.net.Uri;
import android.os.BatteryManager;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.InputStream;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    private static final int PICK_IMAGE=101;
    private static final int[] HAND_COLORS={Color.WHITE,Color.rgb(255,120,40),Color.RED,Color.CYAN,Color.rgb(120,255,120)};
    private static final int[] TEXT_COLORS={Color.WHITE,Color.LTGRAY,Color.rgb(255,180,50),Color.CYAN,Color.GREEN};
    private static final int[] BG_COLORS={Color.BLACK,Color.rgb(24,24,30),Color.rgb(20,35,48),Color.rgb(48,24,24),Color.rgb(25,45,28)};
    private static final String[] FONTS={"Classique","Gras","Fin","Monospace","Serif"};
    private SharedPreferences prefs; private WatchPreview preview;
    private SeekBar bgSeek,handSeek,infoSeek; private CheckBox secondsBox,dateBox,batteryBox,smallDigitalBox;
    private Spinner modeSpinner,digitalFontSpinner,dateFontSpinner; private Button activeBtn,standbyBtn,handColorBtn,textColorBtn,bgColorBtn;
    private boolean standby=false,loading=false; private int handColorIndex=0,textColorIndex=0,bgColorIndex=0;

    @Override protected void onCreate(Bundle b){super.onCreate(b); prefs=getSharedPreferences("ribaut_watch_designer",MODE_PRIVATE);
        ScrollView scroll=new ScrollView(this); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(dp(14),dp(12),dp(14),dp(24)); root.setBackgroundColor(Color.rgb(18,18,22)); scroll.addView(root);
        TextView title=text("Ribaut Watch Designer V2",22,true); title.setGravity(Gravity.CENTER); root.addView(title,matchWrap());
        preview=new WatchPreview(this); root.addView(preview,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(320)));
        LinearLayout pr=horizontal(); activeBtn=button("ACTIF"); standbyBtn=button("VEILLE"); pr.addView(activeBtn,weighted()); pr.addView(standbyBtn,weighted()); root.addView(pr,matchWrap()); activeBtn.setOnClickListener(v->switchProfile(false)); standbyBtn.setOnClickListener(v->switchProfile(true));
        root.addView(section("Type de cadran")); modeSpinner=spinner(new String[]{"Analogique","Numérique"}); root.addView(modeSpinner,matchWrap());
        smallDigitalBox=check("Ajouter une petite heure numérique sur le cadran analogique"); root.addView(smallDigitalBox,matchWrap());
        root.addView(section("Police de l'heure numérique")); digitalFontSpinner=spinner(FONTS); root.addView(digitalFontSpinner,matchWrap());
        root.addView(section("Police de la date")); dateFontSpinner=spinner(FONTS); root.addView(dateFontSpinner,matchWrap());
        Button photoBtn=button("Choisir une photo de fond"); root.addView(photoBtn,matchWrap()); photoBtn.setOnClickListener(v->choosePhoto());
        root.addView(section("Apparence du mode sélectionné")); bgSeek=addSlider(root,"Éclairage visuel du fond",100); handSeek=addSlider(root,"Aiguilles / chiffres",100); infoSeek=addSlider(root,"Texte / informations",100);
        secondsBox=check("Afficher les secondes"); dateBox=check("Afficher la date (lun, mar, mer…)"); batteryBox=check("Afficher la batterie"); root.addView(secondsBox,matchWrap()); root.addView(dateBox,matchWrap()); root.addView(batteryBox,matchWrap());
        LinearLayout cr=horizontal(); bgColorBtn=button("Fond"); handColorBtn=button("Aiguilles"); cr.addView(bgColorBtn,weighted()); cr.addView(handColorBtn,weighted()); root.addView(cr,matchWrap()); textColorBtn=button("Couleur du texte"); root.addView(textColorBtn,matchWrap());
        bgColorBtn.setOnClickListener(v->{bgColorIndex=(bgColorIndex+1)%BG_COLORS.length;saveProfile();apply();colors();}); handColorBtn.setOnClickListener(v->{handColorIndex=(handColorIndex+1)%HAND_COLORS.length;saveProfile();apply();colors();}); textColorBtn.setOnClickListener(v->{textColorIndex=(textColorIndex+1)%TEXT_COLORS.length;saveProfile();apply();colors();});
        SeekBar.OnSeekBarChangeListener sl=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean f){if(!loading)apply();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){saveProfile();}}; bgSeek.setOnSeekBarChangeListener(sl);handSeek.setOnSeekBarChangeListener(sl);infoSeek.setOnSeekBarChangeListener(sl);
        View.OnClickListener ol=v->{saveProfile();apply();}; secondsBox.setOnClickListener(ol);dateBox.setOnClickListener(ol);batteryBox.setOnClickListener(ol);smallDigitalBox.setOnClickListener(ol);
        android.widget.AdapterView.OnItemSelectedListener il=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(!loading){saveProfile();apply();}}public void onNothingSelected(android.widget.AdapterView<?> p){}}; modeSpinner.setOnItemSelectedListener(il);digitalFontSpinner.setOnItemSelectedListener(il);dateFontSpinner.setOnItemSelectedListener(il);
        LinearLayout ar=horizontal(); Button save=button("ENREGISTRER"),reset=button("RÉINITIALISER"); ar.addView(save,weighted());ar.addView(reset,weighted());root.addView(ar,matchWrap()); save.setOnClickListener(v->{saveProfile();Toast.makeText(this,"Projet enregistré",Toast.LENGTH_SHORT).show();}); reset.setOnClickListener(v->reset());
        Button install=button("INSTALLER SUR LA WATCH 8");root.addView(install,matchWrap());install.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Installation Watch 8").setMessage("La liaison d'installation vers la montre est en cours d'intégration sur cette branche de test.").setPositiveButton("OK",null).show());
        setContentView(scroll); loadImage(); loadProfile(); }

    private Spinner spinner(String[] values){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));return s;}
    private void choosePhoto(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,PICK_IMAGE);}
    @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==PICK_IMAGE&&c==RESULT_OK&&d!=null&&d.getData()!=null){Uri u=d.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}prefs.edit().putString("background_uri",u.toString()).apply();preview.loadBitmap(u);}}
    private String suffix(){return standby?"_s":"_a";} private void switchProfile(boolean s){if(standby==s)return;saveProfile();standby=s;loadProfile();}
    private void loadProfile(){loading=true;String s=suffix();bgSeek.setProgress(prefs.getInt("bg"+s,standby?10:80));handSeek.setProgress(prefs.getInt("hands"+s,standby?40:100));infoSeek.setProgress(prefs.getInt("info"+s,standby?45:100));secondsBox.setChecked(prefs.getBoolean("seconds"+s,!standby));dateBox.setChecked(prefs.getBoolean("date"+s,true));batteryBox.setChecked(prefs.getBoolean("battery"+s,true));smallDigitalBox.setChecked(prefs.getBoolean("smallDigital"+s,false));modeSpinner.setSelection(prefs.getInt("mode"+s,0));digitalFontSpinner.setSelection(prefs.getInt("digitalFont"+s,1));dateFontSpinner.setSelection(prefs.getInt("dateFont"+s,0));bgColorIndex=prefs.getInt("bgColor"+s,0)%BG_COLORS.length;handColorIndex=prefs.getInt("handColor"+s,0)%HAND_COLORS.length;textColorIndex=prefs.getInt("textColor"+s,0)%TEXT_COLORS.length;loading=false;activeBtn.setEnabled(standby);standbyBtn.setEnabled(!standby);colors();apply();}
    private void saveProfile(){if(loading||bgSeek==null)return;String s=suffix();prefs.edit().putInt("bg"+s,bgSeek.getProgress()).putInt("hands"+s,handSeek.getProgress()).putInt("info"+s,infoSeek.getProgress()).putBoolean("seconds"+s,secondsBox.isChecked()).putBoolean("date"+s,dateBox.isChecked()).putBoolean("battery"+s,batteryBox.isChecked()).putBoolean("smallDigital"+s,smallDigitalBox.isChecked()).putInt("mode"+s,modeSpinner.getSelectedItemPosition()).putInt("digitalFont"+s,digitalFontSpinner.getSelectedItemPosition()).putInt("dateFont"+s,dateFontSpinner.getSelectedItemPosition()).putInt("bgColor"+s,bgColorIndex).putInt("handColor"+s,handColorIndex).putInt("textColor"+s,textColorIndex).apply();}
    private void reset(){String s=suffix();SharedPreferences.Editor e=prefs.edit();String[] k={"bg","hands","info","seconds","date","battery","smallDigital","mode","digitalFont","dateFont","bgColor","handColor","textColor"};for(String x:k)e.remove(x+s);e.apply();loadProfile();}
    private void apply(){if(preview==null||bgSeek==null)return;preview.digital=modeSpinner.getSelectedItemPosition()==1;preview.smallDigital=smallDigitalBox.isChecked();preview.standby=standby;preview.showSeconds=secondsBox.isChecked();preview.showDate=dateBox.isChecked();preview.showBattery=batteryBox.isChecked();preview.bgPercent=bgSeek.getProgress();preview.handPercent=handSeek.getProgress();preview.infoPercent=infoSeek.getProgress();preview.bgColor=BG_COLORS[bgColorIndex];preview.handColor=HAND_COLORS[handColorIndex];preview.textColor=TEXT_COLORS[textColorIndex];preview.digitalFont=digitalFontSpinner.getSelectedItemPosition();preview.dateFont=dateFontSpinner.getSelectedItemPosition();preview.invalidate();}
    private void loadImage(){String s=prefs.getString("background_uri",null);if(s!=null)try{preview.loadBitmap(Uri.parse(s));}catch(Exception ignored){}}
    private void colors(){bgColorBtn.setTextColor(BG_COLORS[bgColorIndex]);handColorBtn.setTextColor(HAND_COLORS[handColorIndex]);textColorBtn.setTextColor(TEXT_COLORS[textColorIndex]);}
    private SeekBar addSlider(LinearLayout r,String l,int max){TextView t=text(l,14,false);t.setTextColor(Color.LTGRAY);r.addView(t,matchWrap());SeekBar b=new SeekBar(this);b.setMax(max);r.addView(b,matchWrap());return b;}
    private TextView section(String s){TextView t=text(s,16,true);return t;} private TextView text(String s,int sp,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(Color.WHITE);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;} private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;} private CheckBox check(String s){CheckBox c=new CheckBox(this);c.setText(s);c.setTextColor(Color.WHITE);return c;} private LinearLayout horizontal(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER);return l;} private LinearLayout.LayoutParams weighted(){return new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f);} private LinearLayout.LayoutParams matchWrap(){return new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);} private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}

    public static class WatchPreview extends View{
        private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private Bitmap bitmap;boolean digital,smallDigital,standby,showSeconds=true,showDate=true,showBattery=true;int bgPercent=80,handPercent=100,infoPercent=100,bgColor=Color.BLACK,handColor=Color.WHITE,textColor=Color.WHITE,digitalFont=1,dateFont=0;
        WatchPreview(MainActivity c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);} void loadBitmap(Uri u){try(InputStream in=getContext().getContentResolver().openInputStream(u)){bitmap=BitmapFactory.decodeStream(in);invalidate();}catch(Exception ignored){}}
        private Typeface font(int i){switch(i){case 1:return Typeface.DEFAULT_BOLD;case 2:return Typeface.create("sans-serif-light",Typeface.NORMAL);case 3:return Typeface.MONOSPACE;case 4:return Typeface.SERIF;default:return Typeface.DEFAULT;}}
        @Override protected void onDraw(Canvas c){super.onDraw(c);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())/2f-10;Path clip=new Path();clip.addCircle(cx,cy,r,Path.Direction.CW);c.save();c.clipPath(clip);p.setColor(Color.BLACK);p.setStyle(Paint.Style.FILL);p.setAlpha(255);c.drawCircle(cx,cy,r,p);if(bitmap!=null)drawImage(c,cx-r,cy-r,cx+r,cy+r);else{p.setColor(bgColor);p.setAlpha(alpha(bgPercent));c.drawCircle(cx,cy,r,p);}Date now=new Date();if(digital)drawDigital(c,cx,cy,r,now,false);else{drawAnalog(c,cx,cy,r);if(smallDigital)drawDigital(c,cx,cy+r*.42f,r,now,true);}drawInfo(c,cx,cy,r,now);c.restore();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);p.setColor(Color.DKGRAY);p.setAlpha(255);c.drawCircle(cx,cy,r,p);}
        private void drawAnalog(Canvas c,float cx,float cy,float r){Calendar cal=Calendar.getInstance();int h=cal.get(Calendar.HOUR),m=cal.get(Calendar.MINUTE),s=cal.get(Calendar.SECOND);for(int i=0;i<12;i++){double a=Math.toRadians(i*30-90);p.setColor(handColor);p.setAlpha(alpha(handPercent));p.setStrokeWidth(i%3==0?5:3);c.drawLine(cx+(float)Math.cos(a)*r*.78f,cy+(float)Math.sin(a)*r*.78f,cx+(float)Math.cos(a)*r*.87f,cy+(float)Math.sin(a)*r*.87f,p);}hand(c,cx,cy,r*.48f,(h+m/60f)*30-90,9);hand(c,cx,cy,r*.68f,m*6-90,6);if(showSeconds)hand(c,cx,cy,r*.74f,s*6-90,2.5f);}
        private void hand(Canvas c,float cx,float cy,float len,float deg,float w){double a=Math.toRadians(deg);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(w);p.setColor(handColor);p.setAlpha(alpha(handPercent));c.drawLine(cx,cy,cx+(float)Math.cos(a)*len,cy+(float)Math.sin(a)*len,p);}
        private void drawDigital(Canvas c,float cx,float cy,float r,Date d,boolean small){String pat=showSeconds&&!small?"HH:mm:ss":"HH:mm";p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(handColor);p.setAlpha(alpha(handPercent));p.setTypeface(font(digitalFont));p.setTextSize(r*(small?.16f:(showSeconds?.28f:.34f)));c.drawText(new SimpleDateFormat(pat,Locale.FRANCE).format(d),cx,cy,p);}
        private void drawInfo(Canvas c,float cx,float cy,float r,Date d){p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(textColor);p.setAlpha(alpha(infoPercent));if(showDate){p.setTypeface(font(dateFont));p.setTextSize(r*.105f);String v=new SimpleDateFormat("EEE dd MMM",Locale.FRANCE).format(d).replace(".","").toLowerCase(Locale.FRANCE);c.drawText(v,cx,cy+r*.58f,p);}if(showBattery){BatteryManager bm=(BatteryManager)getContext().getSystemService(BATTERY_SERVICE);int n=bm!=null?bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY):-1;p.setTypeface(Typeface.DEFAULT);p.setTextSize(r*.095f);c.drawText(n>=0?"Batterie "+n+"%":"Batterie --%",cx,cy+r*.73f,p);}}
        private void drawImage(Canvas c,float l,float t,float rr,float b){float dw=rr-l,dh=b-t,sc=Math.max(dw/bitmap.getWidth(),dh/bitmap.getHeight());int sw=Math.max(1,Math.round(dw/sc)),sh=Math.max(1,Math.round(dh/sc)),sx=Math.max(0,(bitmap.getWidth()-sw)/2),sy=Math.max(0,(bitmap.getHeight()-sh)/2);p.setAlpha(alpha(bgPercent));c.drawBitmap(bitmap,new Rect(sx,sy,Math.min(bitmap.getWidth(),sx+sw),Math.min(bitmap.getHeight(),sy+sh)),new RectF(l,t,rr,b),p);p.setAlpha(255);} private int alpha(int x){return Math.max(0,Math.min(255,Math.round(x*2.55f)));}
    }
}
